module serial2parallel (
    input clk, 
    input rst_n, 
    input din_serial, 
    input din_valid, 
    output reg [7:0] dout_parallel, 
    output reg dout_valid
);
// Internal signals
reg [3:0] cnt;
// Sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 4'd0;
        dout_parallel <= 8'd0;
        dout_valid <= 1'b0;
    end else begin
        case ({din_valid, cnt})
            {1'b1, 4'd0}: begin
                dout_parallel[7] <= din_serial;
                cnt <= cnt + 1;
            end
            {1'b1, 4'd1}: begin
                dout_parallel[6] <= din_serial;
                cnt <= cnt + 1;
            end
            {1'b1, 4'd2}: begin
                dout_parallel[5] <= din_serial;
                cnt <= cnt + 1;
            end
            {1'b1, 4'd3}: begin
                dout_parallel[4] <= din_serial;
                cnt <= cnt + 1;
            end
            {1'b1, 4'd4}: begin
                dout_parallel[3] <= din_serial;
                cnt <= cnt + 1;
            end
            {1'b1, 4'd5}: begin
                dout_parallel[2] <= din_serial;
                cnt <= cnt + 1;
            end
            {1'b1, 4'd6}: begin
                dout_parallel[1] <= din_serial;
                cnt <= cnt + 1;
            end
            {1'b1, 4'd7}: begin
                dout_parallel[0] <= din_serial;
                cnt <= cnt + 1;
            end
            default: begin
                cnt <= 4'd0;
                dout_valid <= 1'b0;
            end
        endcase

        // Set dout_valid to 1 when cnt reaches 8
        if (cnt == 4'd8) begin
            dout_valid <= 1'b1;
        end else begin
            dout_valid <= 1'b0;
        end
    end
end
endmodule
